/**
 * The original Windows 95 system sounds the app can play:
 * - `chord`: The alert chord every error raises.
 * - `ding`: The informational dialog beep.
 * - `chimes`: The passive notification chime.
 * - `tada`: The completion fanfare.
 * - `startup`: The boot sound.
 */
export type AppSound = "chimes" | "chord" | "ding" | "startup" | "tada"
